import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'pricing-card-1-label';

  const pos = config.scenePosition || { x: -3.2, y: 1, z: 0.06 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const imgTex = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  imgTex.colorSpace = THREE.SRGBColorSpace;

  const inkColor = uniform(new THREE.Color('#16161d'));
  const surfaceColor = uniform(new THREE.Color('#0b0b10'));
  const grainStrength = uniform(0.035);

  const material = new THREE.MeshBasicNodeMaterial();

  const vUv = uv();
  const gradient = mix(surfaceColor, inkColor, vUv.y);

  const texSample = texture(imgTex, vUv);

  // simple pseudo-random grain based on uv
  const grainSeed = vUv.x.mul(12.9898).add(vUv.y.mul(78.233)).sin().mul(43758.5453);
  const grainVal = grainSeed.fract().sub(0.5).mul(grainStrength);

  const composited = mix(gradient, texSample.rgb, texSample.a).add(grainVal);

  material.colorNode = vec4(composited, float(1.0));
  material.transparent = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'pricing-card-1-label-surface';
  group.add(mesh);

  // Headline text: "Pricing 1"
  const textMesh = createTextMesh({
    text: 'Pricing 1',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    atlas: ctx.fontAtlas,
    align: 'center',
    anchor: 'center'
  });

  if (textMesh) {
    textMesh.position.set(0, 0, 0.001);
    group.add(textMesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imgTex) imgTex.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach(m => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
